// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"ja","terms":[["aml","AML（マネーロンダリング対策）","AMLとは、犯罪で得た資金の出どころを隠す行為（マネーロンダリング）を防ぐために、金融機関や暗号資産取引所が行う監視・確認・報告の仕組み全体のことです。","regulation",1],["amm","AMM（自動マーケットメーカー）","AMM（自動マーケットメーカー）とは、板で売り手と買い手を突き合わせる代わりに、流動性プールと数式で自動的に価格を決めて取引を成立させる仕組みです。","defi",1],["apr-vs-apy","APRとAPYの違い（年利・年間利回り）","APRは複利を含まない単純な年利、APYは得た利息を再投資する複利効果を含めた年間利回りで、同じ金利でもAPYの方が高い数字になります。","defi",1],["cbdc","CBDC（中央銀行デジタル通貨）","CBDCとは、中央銀行が発行し、現金や中央銀行預金と同じく中央銀行の直接の負債となるデジタル形式の法定通貨のことです。","stablecoins",1],["dao","DAO（分散型自律組織）","DAO（分散型自律組織）とは、特定の経営者ではなく、トークン保有者などの参加者がブロックチェーン上の投票で意思決定を行う組織の形態です。","defi",1],["defi","DeFi（分散型金融）","DeFi（分散型金融）とは、銀行や取引所などの仲介者を通さず、ブロックチェーン上のスマートコントラクトで交換、貸し借り、利回り運用などを行う金融サービスの総称です。","defi",1],["defi-lending","DeFiレンディング","DeFiレンディングとは、スマートコントラクト上で暗号資産を貸し出して利息を得たり、担保を預けて別の暗号資産を借りたりできる仕組みです。","defi",1],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。","defi",1],["fomo","FOMO（フォーモ）","FOMOとは「Fear Of Missing Out」の略で、値上がりに乗り遅れることへの不安から、冷静な判断をせずに買ってしまう心理のことです。","basics",1],["fud","FUD（ファッド）","FUDとは「Fear, Uncertainty and Doubt（恐怖・不確実性・疑念）」の略で、市場に不安を広げ、売りを誘うような情報や雰囲気のことです。","basics",1],["hodl","HODL（ガチホ）","HODL（ガチホ）とは、価格の上下に関係なく暗号資産を売らずに長期保有し続ける投資スタイルのことで、日本では「ガチホ」とも呼ばれます。","basics",1],["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。","regulation",1],["no-kyc-exchange","KYC不要の取引所（ノーKYC取引所）","KYC不要の取引所とは、身分証明書による本人確認なしで登録や取引、一定額までの出金ができる暗号資産取引所や交換サービスのことです。","regulation",1],["mev","MEV（最大抽出可能価値）","MEV（最大抽出可能価値）とは、ブロックに入れる取引の順番を並べ替えたり、取引を差し込んだりすることで、ブロック生成者や専門のボットが得られる追加の利益のことです。","defi",1],["mica","MiCA（EU暗号資産市場規則）","MiCAとは、EU全体で暗号資産の発行者とサービス提供者に共通のルールを定めた規則で、ステーブルコインや取引所などの認可、情報開示、利用者保護を定めています。","regulation",1],["nft","NFT（非代替性トークン）","NFT（非代替性トークン）とは、1つ1つが固有の識別番号を持ち、他と交換可能ではないデジタルトークンで、アートやゲームアイテム、会員権などの所有を表すのに使われます。","defi",1],["oco-order","OCO注文","OCO注文とは、2つの注文を同時に出し、どちらか一方が約定するともう一方が自動的に取り消される注文方法です。","trading",1],["p2p-trading","P2P取引（個人間取引）","P2P取引とは、取引所が仲介役となり、利用者同士が銀行振込などの法定通貨とUSDTなどの暗号資産を直接交換する取引方法です。","exchange-features",1],["real-world-assets","RWA（現実資産のトークン化）","RWAとは、国債、株式、不動産、金、貸付債権など、ブロックチェーンの外にある現実の資産を、トークンとしてブロックチェーン上で表現したもの、またはその分野のことです。","tokenized-assets",1],["total-value-locked","TVL（預かり資産総額）","TVLとは、DeFiのプロトコルやブロックチェーンに預けられている暗号資産の総額をドルなどで表した指標で、利用規模の目安として使われます。","defi",1],["usdc","USDC（USDコイン）","USDCとは、米国のCircle社が発行する米ドル連動型のステーブルコインで、現金と米国短期国債などを裏付けに1 USDCが約1ドルになるよう設計されています。","stablecoins",1],["usdt","USDT（テザー）","USDT（テザー）とは、Tether社が発行する米ドル連動型のステーブルコインで、暗号資産取引の基軸通貨として最も広く使われているもののひとつです。","stablecoins",1],["usdt-margined-futures","USDT建て先物（リニア先物）","USDT建て先物（リニア先物）とは、証拠金と損益をステーブルコインのUSDTで計算する先物契約で、価格の変化と損益が比例するためわかりやすいのが特徴です。","derivatives",1],["vasp","VASP（暗号資産サービス提供者）","VASPとは、暗号資産の交換、送金、保管などのサービスを業として提供する事業者を指すFATFの用語で、取引所やカストディ業者などが該当します。","regulation",1],["vip-tier","VIPランク（手数料ティア）","VIPランクとは、取引所が利用者の取引量や資産残高に応じて設定する段階的な会員区分で、ランクが上がるほど取引手数料が安くなる仕組みです。","exchange-features",1],["arbitrage","アービトラージ（裁定取引）","アービトラージ（裁定取引）とは、同じ資産の価格差が取引所間や市場間で生じたときに、安い方で買って高い方で売り、その差を利益にする取引です。","trading",1],["active-addresses","アクティブアドレス数","アクティブアドレス数とは、一定期間内に送金または受取の取引に関わったブロックチェーン上のアドレスの数で、ネットワークの利用状況を測るオンチェーン指標です。","onchain",1],["address-poisoning","アドレスポイズニング","アドレスポイズニングとは、本物の送金先とよく似たアドレスから少額や0円の取引を送りつけ、取引履歴から偽アドレスをコピーさせて誤送金を誘う詐欺です。","wallets-security",1],["algorithmic-stablecoin","アルゴリズム型ステーブルコイン","アルゴリズム型ステーブルコインとは、十分な担保ではなく、供給量を自動調整するプログラムや別トークンとの交換の仕組みによって価格を1ドルに保とうとするステーブルコインです。","stablecoins",1],["altcoin","アルトコイン","アルトコインとは、ビットコイン以外の暗号資産の総称で、イーサリアムやソラナのような大型銘柄から、新しく小規模な銘柄までを含みます。","basics",1],["ethereum","イーサリアム（ETH）","イーサリアム（ETH）とは、スマートコントラクトを実行できるブロックチェーンと、その手数料の支払いやステーキングに使われるネイティブ暗号資産ETHのことです。","basics",1],["yield-farming","イールドファーミング","イールドファーミングとは、DeFiのプロトコルに暗号資産を預けたり流動性を提供したりして、手数料や報酬トークンなどの利回りを得る運用方法です。","defi",1],["index-price","インデックス価格","インデックス価格とは、複数の主要な現物取引所の価格を加重平均して算出した、その暗号資産の現物の基準価格のことで、マーク価格や資金調達率の計算に使われます。","derivatives",1],["impermanent-loss","インパーマネントロス（変動損失）","インパーマネントロスとは、AMMの流動性プールに資産を預けている間にトークンの価格比が変わることで、単に保有していた場合より資産価値が少なくなる損失のことです。","defi",1],["wash-trading","ウォッシュトレード（仮装売買）","ウォッシュトレード（仮装売買）とは、同じ人物や協力関係にある者同士が自分で買って自分で売り、実態のない取引を作って取引量や価格を偽装する行為です。","trading",1],["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。","wallets-security",1],["airdrop","エアドロップ","エアドロップとは、プロジェクトが特定の条件を満たしたウォレットやユーザーに、トークンを無料で配布することです。","basics",1],["options","オプション取引（暗号資産オプション）","オプション取引とは、ある資産を将来の決められた日に、決められた価格（権利行使価格）で買う権利（コール）または売る権利（プット）を売買する取引です。","derivatives",1],["oracle","オラクル（ブロックチェーンオラクル）","オラクルとは、価格や天気、試合結果など、ブロックチェーンの外にあるデータをスマートコントラクトに届ける仕組みのことです。","defi",1],["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。","onchain",1],["custodial-wallet","カストディアルウォレット（管理型ウォレット）","カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。","wallets-security",1],["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。","basics",1],["governance-token","ガバナンストークン","ガバナンストークンとは、DeFiやDAOなどのプロジェクトで、運営方針や仕様変更に関する投票に参加する権利を表すトークンです。","defi",1],["whale","クジラ（大口投資家）","クジラとは、特定の暗号資産を大量に保有し、その売買や送金が市場価格に影響を与えるほどの規模を持つ大口の投資家やアドレスのことです。","trading",1],["grid-trading-bot","グリッドトレードボット","グリッドトレードボットとは、設定した価格帯をいくつかの網目（グリッド）に分け、価格が下がれば買い、上がれば売る指値注文を自動で繰り返す取引ツールのことです。","exchange-features",1],["cross-chain-bridge","クロスチェーンブリッジ","クロスチェーンブリッジとは、異なるブロックチェーン間で暗号資産やデータを移動できるようにする仕組みで、たとえばイーサリアムのUSDCをレイヤー2に移すときに使われます。","defi",1],["cross-margin","クロスマージン","クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。","derivatives",1],["coin-vs-token","コインとトークンの違い","コインとトークンの違いとは、コインは独自のブロックチェーンのネイティブ資産であり、トークンは既存のブロックチェーン上でスマートコントラクトにより発行される資産だという区別です。","basics",1],["coin-margined-futures","コイン建て先物（インバース先物）","コイン建て先物（インバース先物）とは、証拠金と損益をUSDTではなくBTCやETHなどのコインそのもので受け渡す先物契約で、契約サイズは米ドル建てで表されるのが一般的です。","derivatives",1],["cold-wallet","コールドウォレット（コールドストレージ）","コールドウォレットとは、秘密鍵をインターネットから切り離した環境で保管する暗号資産の保管方法で、遠隔からのハッキングを受けにくいのが特徴です。","wallets-security",1],["copy-trading","コピートレード","コピートレードとは、取引所上で選んだ他のトレーダーの売買を、自分の口座で自動的に同じように再現する仕組みのことです。","exchange-features",1],["instant-convert","コンバート（簡単交換）","コンバートとは、取引所が提示した価格で、板を使わずにある暗号資産を別の暗号資産やステーブルコインにワンタップで交換できる機能のことです。","exchange-features",1],["satoshi","サトシ（sats）","サトシ（sats）とは、ビットコインの最小単位で、1サトシは1億分の1 BTC（0.00000001 BTC）に相当します。","basics",1],["sub-account","サブアカウント","サブアカウントとは、1つのメインアカウントの下に作成できる独立した口座で、資金や取引、APIキーを用途ごとに分けて管理するための取引所の機能です。","exchange-features",1],["support-and-resistance","サポートライン・レジスタンスライン（支持線・抵抗線）","サポートライン・レジスタンスラインとは、過去に下落が止まりやすかった価格帯（支持線）と、上昇が止まりやすかった価格帯（抵抗線）をチャート上に示したものです。","trading",1],["seed-phrase","シードフレーズ（リカバリーフレーズ）","シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。","wallets-security",1],["short-squeeze","ショートスクイーズ（踏み上げ）","ショートスクイーズ（踏み上げ）とは、価格の上昇によってショートを持つ人が損切りや強制ロスカットで一斉に買い戻し、その買いがさらに価格を押し上げる現象です。","derivatives",1],["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。","defi",1],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。","stablecoins",1],["stop-limit-order","ストップリミット注文","ストップリミット注文とは、価格がトリガー価格（ストップ価格）に達したときに、あらかじめ指定した価格で指値注文を自動発注する注文方法です。","trading",1],["bid-ask-spread","スプレッド（売買価格差）","スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。","trading",1],["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。","basics",1],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。","trading",1],["depeg","デペッグ（Depeg）","デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。","stablecoins",1],["demo-trading","デモトレード","デモトレードとは、取引所が用意した仮想資金を使い、実際のお金を使わずに本番とほぼ同じ画面で取引を練習できる機能のことです。","exchange-features",1],["dual-investment","デュアル投資（Dual Investment）","デュアル投資とは、あらかじめ決めた価格（ターゲット価格）と期日を設定し、期日の価格に応じて元本と利息を暗号資産かステーブルコインのどちらかで受け取る仕組み商品です。","exchange-features",1],["tokenomics","トークノミクス","トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。","basics",1],["token-unlock","トークンアンロック","トークンアンロックとは、チームや投資家などに配分されロックされていたトークンが、決められたスケジュールに従って売却や移転できるようになることです。","basics",1],["token-burn","トークンバーン（焼却）","トークンバーン（焼却）とは、トークンを誰も取り出せないアドレスに送ったりコントラクトで消滅させたりして、流通から永久に取り除くことです。","basics",1],["tokenized-gold","トークン化ゴールド（金トークン）","トークン化ゴールドとは、発行体が保管する現物の金に裏付けられ、その金の一定量を表すトークンとしてブロックチェーン上で取引できる暗号資産のことです。","tokenized-assets",1],["tokenized-stocks","トークン化株式","トークン化株式とは、実際の株式や株式に連動する権利をブロックチェーン上のトークンとして発行し、暗号資産と同じように保有や送金ができるようにしたものです。","tokenized-assets",1],["tokenized-treasuries","トークン化国債","トークン化国債とは、米国債などの国債や、国債で運用するファンドの持分をブロックチェーン上のトークンとして発行し、その利回りをオンチェーンで受け取れるようにしたものです。","tokenized-assets",1],["token-approval","トークン承認（Approve・アローワンス）","トークン承認とは、DEXなどのスマートコントラクトに、あなたのウォレットから特定のトークンを指定量まで引き出す権限を与える操作です。","wallets-security",1],["travel-rule","トラベルルール","トラベルルールとは、暗号資産を取引所間などで送るときに、送金人と受取人の氏名などの情報を事業者同士で共有することを求める国際的なルールです。","regulation",1],["transaction-hash","トランザクションハッシュ（TxID）","トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。","wallets-security",1],["dollar-cost-averaging","ドルコスト平均法（DCA）","ドルコスト平均法（DCA）とは、価格に関係なく一定の金額を定期的に買い続けることで、購入タイミングを分散させる投資手法です。","trading",1],["trailing-stop","トレーリングストップ","トレーリングストップとは、価格が有利な方向に動くと損切り価格も自動で追いかけて移動し、反転して一定幅戻ったときに決済する注文です。","trading",1],["node","ノード（Node）","ノードとは、ブロックチェーンのネットワークに参加し、取引やブロックのデータを保存・検証・中継するコンピューターのことです。","onchain",1],["non-custodial-wallet","ノンカストディアルウォレット（セルフカストディ）","ノンカストディアルウォレットとは、秘密鍵やシードフレーズを取引所などの第三者ではなく、利用者自身が管理する暗号資産ウォレットのことです。","wallets-security",1],["hardware-wallet","ハードウェアウォレット","ハードウェアウォレットとは、秘密鍵を専用の小型デバイス内に保管し、送金の署名を端末の中だけで行う物理的な暗号資産ウォレットです。","wallets-security",1],["perp-dex","パーペチュアルDEX（オンチェーン無期限先物）","パーペチュアルDEXとは、無期限先物（パーペチュアル）を、自分のウォレットから証拠金を入れてブロックチェーン上で取引できる分散型取引所です。","defi",1],["hash-rate","ハッシュレート","ハッシュレートとは、プルーフ・オブ・ワーク（PoW）のブロックチェーンでマイニング機器が1秒間に計算できるハッシュの回数のことで、ネットワーク全体の計算力を表します。","onchain",1],["validator","バリデーター（検証者）","バリデーターとは、プルーフ・オブ・ステークのブロックチェーンで暗号資産をステークし、ブロックの提案や取引の検証を行うネットワーク参加者のことです。","basics",1],["bitcoin","ビットコイン（BTC）","ビットコイン（BTC）とは、2009年に運用が始まった最初の暗号資産で、発行上限2100万枚、管理者のいないネットワークでプルーフ・オブ・ワークにより運営されています。","basics",1],["spot-bitcoin-etf","ビットコイン現物ETF","ビットコイン現物ETFとは、運用会社が実際のビットコインを保有し、その価格に連動するよう設計された、証券取引所に上場している投資信託のことです。","regulation",1],["bitcoin-halving","ビットコイン半減期","ビットコイン半減期とは、21万ブロックごと（約4年ごと）に、マイナーが受け取る新規発行のブロック報酬が半分になるイベントのことです。","basics",1],["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。","wallets-security",1],["anti-phishing-code","フィッシング対策コード","フィッシング対策コードとは、取引所から届く正規のメールに利用者が設定した合言葉を表示させ、偽メールと見分けやすくする機能です。","wallets-security",1],["flash-loan","フラッシュローン","フラッシュローンとは、担保なしで暗号資産を借りられる代わりに、同じトランザクション内で必ず返済しなければならないDeFi特有の借入です。","defi",1],["proof-of-stake","プルーフ・オブ・ステーク（PoS）","プルーフ・オブ・ステーク（PoS）とは、暗号資産を担保として預け入れ（ステーク）したバリデーターが、ブロックの提案と検証を担うコンセンサスの仕組みです。","basics",1],["proof-of-work","プルーフ・オブ・ワーク（PoW）","プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。","basics",1],["block-explorer","ブロックエクスプローラー","ブロックエクスプローラーとは、ブロックチェーン上の取引、アドレスの残高、ブロックの情報を検索して閲覧できるウェブサービスのことです。","onchain",1],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。","basics",1],["block-confirmations","ブロック承認数（コンファメーション）","ブロック承認数とは、取引が含まれたブロックの後にいくつのブロックが積み重なったかを示す数で、多いほど取引が覆される可能性が低くなります。","wallets-security",1],["futures-basis","ベーシス（先物と現物の価格差）","ベーシスとは、先物価格と現物価格の差のことで、先物が現物より高い状態をプレミアム（コンタンゴ）、安い状態をディスカウント（バックワーデーション）と呼びます。","derivatives",1],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。","derivatives",1],["portfolio-margin","ポートフォリオマージン","ポートフォリオマージンとは、口座内のすべてのポジションをまとめて評価し、互いに打ち消し合うリスクを考慮して必要な証拠金を計算する方式です。","derivatives",1],["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。","trading",1],["post-only-order","ポストオンリー注文","ポストオンリー注文とは、板に並ぶメイカー注文としてのみ受け付けられ、すぐに約定してテイカーになる場合は自動で取り消される指値注文の設定です。","trading",1],["hot-wallet","ホットウォレット","ホットウォレットとは、インターネットに接続された状態で秘密鍵を扱う暗号資産ウォレットのことで、すぐに送金できる反面、オンライン攻撃の対象になりやすいものです。","wallets-security",1],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。","basics",1],["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。","derivatives",1],["market-maker","マーケットメイカー（MM）","マーケットメイカーとは、買い注文と売り注文の両方を板に出し続けて、他の参加者がいつでも売買できる状態を作る事業者やトレーダーのことです。","trading",1],["margin-call","マージンコール（追証）","マージンコールとは、損失によって証拠金が一定の水準を下回ったときに、取引所が追加の入金やポジションの縮小を求める警告や通知のことです。","derivatives",1],["mining","マイニング（採掘）","マイニング（採掘）とは、プルーフ・オブ・ワークのブロックチェーンで計算処理を行って取引をブロックにまとめ、その報酬として新規発行の暗号資産と手数料を受け取る活動です。","basics",1],["multisig-wallet","マルチシグウォレット","マルチシグウォレットとは、送金に複数の秘密鍵の署名を必要とするウォレットで、たとえば3つの鍵のうち2つの署名がそろわないと資産を動かせない仕組みです。","wallets-security",1],["memecoin","ミームコイン","ミームコインとは、ネット上のジョークや動物、キャラクター、流行などを題材にした暗号資産で、実用性よりもコミュニティの話題性で価格が動きやすい銘柄のことです。","basics",1],["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。","trading",1],["memo-tag","メモ／宛先タグ（Memo・Destination Tag）","メモ（宛先タグ）とは、XRPやXLMなど一部の暗号資産で、同じ入金アドレスを共有する利用者の中から受取人を特定するための追加の番号や文字列です。","wallets-security",1],["mempool","メンプール（Mempool）","メンプールとは、送信されたもののまだブロックに取り込まれていない未承認の取引が一時的に待機している場所のことです。","onchain",1],["rug-pull","ラグプル","ラグプルとは、暗号資産プロジェクトの開発者が流動性や集めた資金を突然引き揚げ、トークンの価格をほぼゼロにして投資家に損失を負わせる詐欺的な行為です。","wallets-security",1],["wrapped-token","ラップトークン（Wrapped Token）","ラップトークンとは、ある暗号資産を別のブロックチェーンや規格で使えるようにするため、元の資産を裏付けとして1対1で発行されたトークンです。","defi",1],["liquid-staking","リキッドステーキング","リキッドステーキングとは、暗号資産をステーキングすると同時に、その預け入れを表すトークンを受け取り、ロックされた資産を他の用途にも使えるようにする仕組みです。","defi",1],["risk-reward-ratio","リスクリワードレシオ（損益比率）","リスクリワードレシオとは、1回の取引で想定する損失額（リスク）と利益額（リワード）の比率のことで、例えば損失100に対して利益200なら1対2と表します。","trading",1],["restaking","リステーキング","リステーキングとは、すでにステーキングしている資産やリキッドステーキングトークンを、別のサービスの安全性確保にも再利用し、追加の報酬を得ようとする仕組みです。","defi",1],["reduce-only-order","リデュースオンリー注文（決済専用注文）","リデュースオンリー注文とは、既存のポジションを減らす方向にしか約定しない注文の設定で、意図せず反対方向の新規ポジションを建ててしまうことを防ぎます。","derivatives",1],["layer-1","レイヤー1（L1）","レイヤー1（L1）とは、ビットコイン、イーサリアム、ソラナのように、独自のネットワークで取引の検証と記録を完結させる基盤となるブロックチェーンのことです。","basics",1],["layer-2","レイヤー2（L2）","レイヤー2（L2）とは、イーサリアムなどのレイヤー1の上で取引をまとめて処理し、その結果をL1に記録することで、手数料を下げ処理を速くする仕組みです。","basics",1],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。","derivatives",1],["candlestick-chart","ローソク足チャート","ローソク足チャートとは、一定期間の始値・高値・安値・終値の4つの価格を、1本のローソクの形で表した価格チャートのことです。","trading",1],["launchpad","ローンチパッド（Launchpad）","ローンチパッドとは、取引所などのプラットフォームを通じて、上場前の新しいトークンを決められた価格で購入できるトークンセールの仕組みのことです。","exchange-features",1],["launchpool","ローンチプール（Launchpool）","ローンチプールとは、取引所が指定した暗号資産やステーブルコインを一定期間預け入れると、新しく上場するトークンを報酬として受け取れる取引所のキャンペーン型サービスです。","exchange-features",1],["long-short-ratio","ロングショート比率","ロングショート比率とは、先物市場でロング（買い）を持っている口座やポジションと、ショート（売り）を持っているものの割合を比べた指標で、市場参加者の偏りを見るのに使われます。","derivatives",1],["long-and-short","ロングとショート（買いポジション・売りポジション）","ロングとショートとは、価格の上昇で利益が出る買いのポジション（ロング）と、価格の下落で利益が出る売りのポジション（ショート）のことです。","derivatives",1],["cryptocurrency","暗号資産（仮想通貨）","暗号資産（仮想通貨）とは、ブロックチェーンなどの技術で発行・管理され、インターネット上で個人間で直接やり取りできるデジタル資産のことです。","basics",1],["crypto-wallet","暗号資産ウォレット（仮想通貨ウォレット）","暗号資産ウォレットとは、暗号資産を送受信するための秘密鍵とアドレスを管理するアプリや機器のことで、コインそのものではなく、それを動かす鍵を保管しています。","wallets-security",1],["crypto-earn","暗号資産の運用サービス（Earn）","暗号資産の運用サービス（Earn）とは、取引所に預けた暗号資産を貸し出しやステーキングなどに回し、利息や報酬を受け取れる取引所の商品群のことです。","exchange-features",1],["crypto-backed-stablecoin","暗号資産担保型ステーブルコイン","暗号資産担保型ステーブルコインとは、ETHなどの暗号資産をスマートコントラクトに預け入れ、その担保価値を上回らない範囲で発行されるステーブルコインのことです。","stablecoins",1],["maintenance-margin","維持証拠金（メンテナンスマージン）","維持証拠金（メンテナンスマージン）とは、ポジションを持ち続けるために口座に残しておかなければならない最低限の証拠金で、これを下回ると強制ロスカット（清算）が始まります。","derivatives",1],["stock-perpetuals","株式の無期限先物（株式パーペチュアル）","株式の無期限先物とは、個別株や株価指数の価格に連動し、満期のない先物契約として証拠金とレバレッジで取引できるデリバティブ商品のことです。","tokenized-assets",1],["fully-diluted-valuation","完全希薄化後時価総額（FDV）","完全希薄化後時価総額（FDV）とは、トークンの現在価格に最大供給量（または総供給量）を掛けた値で、将来すべてのトークンが流通した場合の評価額を示します。","basics",1],["unrealized-pnl","含み損益（未実現損益）","含み損益（未実現損益）とは、まだ決済していないポジションについて、現在の価格で決済したと仮定した場合の利益または損失のことです。","derivatives",1],["bull-market","強気相場（ブルマーケット）","強気相場（ブルマーケット）とは、価格が長期間にわたって上昇傾向を続け、市場参加者の間に楽観的な見方が広がっている相場のことです。","basics",1],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。","derivatives",1],["fear-and-greed-index","恐怖・強欲指数（Fear and Greed Index）","恐怖・強欲指数とは、価格変動率や出来高、SNSの反応などを組み合わせて、市場参加者の心理を0（極度の恐怖）から100（極度の強欲）の数値で表した指標です。","onchain",1],["short-selling","空売り（ショートセリング）","空売り（ショートセリング）とは、持っていない資産を先に売り、後で値下がりしたところで買い戻して差額を利益にする取引方法です。","derivatives",1],["open-interest","建玉（未決済建玉・オープンインタレスト）","建玉（オープンインタレスト）とは、先物やオプションで、まだ決済されずに残っている契約の総数（または総額）のことで、市場にどれだけの資金がポジションとして入っているかを示します。","derivatives",1],["spot-trading","現物取引（スポット取引）","現物取引（スポット取引）とは、暗号資産をその時点の価格で実際に売買し、買った資産をそのまま受け取って保有する取引のことです。","trading",1],["delivery-futures","限月先物（デリバリー先物・四半期先物）","限月先物とは、満期日（決済日）があらかじめ決まっている先物契約で、満期になると自動的に決済され、暗号資産では四半期ごとの契約がよく使われます。","derivatives",1],["public-key","公開鍵（パブリックキー）","公開鍵とは、秘密鍵から計算される暗号の鍵で、取引の署名が正しい秘密鍵で作られたかを誰でも検証できるようにするものです。","wallets-security",1],["synthetic-dollar","合成ドル（デルタニュートラル型ステーブルコイン）","合成ドルとは、暗号資産の現物保有と無期限先物のショートを組み合わせて価格変動を相殺し、ドルに近い価値を保つよう設計されたトークンのことです。代表例はEthenaのUSDeです。","stablecoins",1],["last-price","最終取引価格（直近約定価格）","最終取引価格（直近約定価格）とは、その取引所の板で最後に売買が成立した価格のことで、取引画面やチャートに表示される通常の「現在値」です。","derivatives",1],["all-time-high","史上最高値（ATH）","史上最高値（ATH）とは、ある暗号資産がこれまでに記録した中で最も高い価格のことで、英語のAll-Time Highの略です。","basics",1],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。","trading",1],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。","derivatives",1],["funding-rate-arbitrage","資金調達率アービトラージ（FRアービトラージ）","資金調達率アービトラージとは、現物を買うと同時に同じ数量の無期限先物をショートし、価格変動の影響を打ち消しながら資金調達率の受け取りを狙う取引です。","derivatives",1],["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。","basics",1],["auto-deleveraging","自動デレバレッジ（ADL）","自動デレバレッジ（ADL）とは、清算されたポジションの損失を保険基金で補いきれないときに、反対側で利益が出ているトレーダーのポジションを取引所が強制的に縮小する仕組みです。","derivatives",1],["time-in-force","執行条件（GTC・IOC・FOK）","執行条件（タイムインフォース）とは、注文をいつまで有効にし、約定しなかった分をどう扱うかを決める設定で、代表的なものにGTC・IOC・FOKがあります。","trading",1],["bear-market","弱気相場（ベアマーケット）","弱気相場（ベアマーケット）とは、価格が長期間にわたって下落傾向を続け、悲観的な見方が市場に広がっている相場のことです。","basics",1],["trading-pair","取引ペア（通貨ペア）","取引ペアとは、BTC/USDTやETH/JPYのように、どの資産をどの資産と交換するかを示す組み合わせのことで、取引所の売買はすべてペア単位で行われます。","trading",1],["exchange-netflow","取引所ネットフロー（取引所への流入・流出）","取引所ネットフローとは、一定期間に暗号資産取引所のウォレットへ入った量から出た量を差し引いた数値で、流入超か流出超かを示すオンチェーン指標です。","onchain",1],["trading-volume","取引量（出来高）","取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。","trading",1],["withdrawal-whitelist","出金ホワイトリスト","出金ホワイトリストとは、あらかじめ登録した送金先アドレスにだけ出金できるよう制限する取引所のセキュリティ機能です。","wallets-security",1],["withdrawal-fee","出金手数料","出金手数料とは、取引所から外部のウォレットや他の取引所へ暗号資産を送るときに差し引かれる手数料で、主にブロックチェーンのネットワーク手数料をまかなうためのものです。","exchange-features",1],["proof-of-reserves","準備金証明（プルーフ・オブ・リザーブ）","準備金証明（PoR）とは、取引所が利用者から預かった暗号資産と同額以上の資産を実際に保有していることを、ブロックチェーン上のデータなどで示す仕組みです。","wallets-security",1],["referral-code","紹介コード（手数料キャッシュバック）","紹介コードとは、取引所の口座開設時に入力することで、紹介者と新規利用者の双方に手数料の割引やキャッシュバックなどの特典が付与される仕組みです。","exchange-features",1],["margin-trading","証拠金取引（マージン取引）","証拠金取引（マージン取引）とは、証拠金を担保として取引所から資金や暗号資産を借り、手持ちの資金より大きな金額で売買する取引方法です。","derivatives",1],["token-listing","上場（トークン上場）","トークン上場とは、取引所が新しい暗号資産の取扱いを開始し、利用者がその取引所で入金・売買・出金できるようにすることです。","exchange-features",1],["delisting","上場廃止（デリスティング）","上場廃止とは、取引所がある暗号資産の取扱いを終了し、その取引所での売買、さらに一定期間後には入金や出金もできなくなることです。","exchange-features",1],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。","trading",1],["liquidation-price","清算価格（ロスカット価格）","清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。","derivatives",1],["futures-contract","先物取引（先物契約）","先物取引とは、ある資産を将来の特定の時点に、あらかじめ決めた価格で売買することを約束する契約で、暗号資産では現物を持たずに価格変動の差額だけをやり取りするのが一般的です。","derivatives",1],["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。","wallets-security",1],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。","trading",1],["geo-restrictions","地域制限（利用制限国）","地域制限とは、暗号資産取引所などが法律や規制上の理由から、特定の国や地域に住む人に対してサービスの全部または一部を提供しないことです。","regulation",1],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。","trading",1],["initial-margin","当初証拠金（イニシャルマージン）","当初証拠金（イニシャルマージン）とは、レバレッジをかけたポジションを新しく建てるときに、最低限差し入れる必要がある証拠金の額のことです。","derivatives",1],["unified-trading-account","統合取引口座（UTA）","統合取引口座（UTA）とは、現物、先物、オプションなどの取引を1つの口座でまとめて行い、口座内の資産全体を証拠金として共有できる取引所の口座形態です。","exchange-features",1],["pig-butchering-scam","豚の屠殺詐欺（ピッグブッチャリング）","豚の屠殺詐欺とは、SNSやマッチングアプリで時間をかけて信頼関係を築いた後、偽の投資サイトやアプリに暗号資産を送金させてだまし取る詐欺です。","wallets-security",1],["two-factor-authentication","二段階認証（2FA）","二段階認証（2FA）とは、パスワードに加えて認証アプリのコードやセキュリティキーなど別の要素を求めることで、不正ログインを防ぐ仕組みです。","wallets-security",1],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。","trading",1],["private-key","秘密鍵（プライベートキー）","秘密鍵とは、暗号資産のアドレスから送金するための電子署名を作る秘密の数値で、これを持つ人がそのアドレスの資産を自由に動かせます。","wallets-security",1],["isolated-margin","分離マージン（アイソレーテッドマージン）","分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。","derivatives",1],["insurance-fund","保険基金（インシュアランスファンド）","保険基金とは、先物取引所が強制ロスカットで証拠金を超える損失が出たときの穴埋めに使うために積み立てている資金で、自動デレバレッジの発動を防ぐ役割を持ちます。","derivatives",1],["fiat-on-ramp","法定通貨オンランプ（入金ルート）","法定通貨オンランプとは、円やドルなどの法定通貨を暗号資産に交換するための入口となるサービスや手段のことで、銀行振込、クレジットカード、P2P取引などがあります。","regulation",1],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。","derivatives",1],["take-profit","利益確定注文（テイクプロフィット）","利益確定注文（テイクプロフィット）とは、価格が目標の水準に達したときに自動で決済し、含み益を実際の利益として確定させる注文です。","trading",1],["circulating-supply","流通供給量","流通供給量とは、現在市場で自由に取引できる状態にある暗号資産の枚数のことで、ロック中のトークンやまだ発行されていない分は含まれません。","basics",1],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。","trading",1],["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。","defi",1]]});
